class Solution {
  public int centeredSubarrays(int[] nums) {
    int n = nums.length, count = 0;
    for (int l = 0; l < n; l++) {
      java.util.HashSet<Long> seen = new java.util.HashSet<>();
      long sum = 0;
      for (int r = l; r < n; r++) {
        sum += nums[r];
        seen.add((long) nums[r]);
        if (seen.contains(sum)) count++;
      }
    }
    return count;
  }
}
